  const record = await getCfApprovalV2ById(id);

  if (record.status !== CF_STATUS.IN_PROGRESS) {
    throw new ApiError(httpStatus.BAD_REQUEST, 'This form is no longer in progress');
  }

  // Step 1 (creator resubmitting after send-back) is handled by approve as well
  const currentStep = record.currentStep;
  const stepMaster = await getStepMasterModel(record.storeType).findOne({ stepNumber: currentStep, archive: false });

  if (currentStep === 1) {
    // BD creator re-submits — only creator can advance from step 1
    if (record.createdBy !== userId) {
      throw new ApiError(httpStatus.FORBIDDEN, 'Only the creator can resubmit from Step 1');
    }
  } else {
    if (!isAuthorizedForStep(userId, userRole, stepMaster, record.address?.region)) {
      throw new ApiError(httpStatus.FORBIDDEN, 'You are not authorized to approve this step');
    }
  }

  // A unanimous exception approval waives the missing-required-document check for
  // exactly the one approval that co

nsumes it.
  const exceptionWaiverActive =
    EXCEPTION_APPROVAL_ENABLED_STEPS.includes(currentStep) && record.exceptionApproval?.status === 'APPROVED';

const isAuthorizedForStep = (userId, userRole, stepMaster, cfRegion = null) => {
  if (!stepMaster) return false;

  if ([ROLES.ADMIN, ROLES.CF_READ_ONLY].includes(userRole)) return true;

  if (stepMaster?.approverType === APPROVER_TYPES.USER) {
    return getStepApproverUserIds(stepMaster).includes(userId);
  }

  if (stepMaster?.approverType === APPROVER_TYPES.REGIONAL_USER) {
    return (stepMaster.regionalApprovers || []).some(
      (ra) => ra.approverUserId === userId && (cfRegion ? ra.region === cfRegion : true)
    );
  }

  // BD_REGIONAL_HEAD also acts as BD_LEAD (creator), e.g. when a CF is sent back to step 1
  if (userRole === ROLES.BD_REGIONAL_HEAD && stepMaster?.approverRole?.includes(ROLES.BD_LEAD)) {
    return true;
  }

  return stepMaster?.approverRole?.includes(userRole);
};

