  const obj = await getInvoiceById(id);
  if (!obj) {
    throw new ApiError(httpStatus.NOT_FOUND, 'Invoice not found');
  }

  // We check duplicate invoice number vendor combination only when either of them is passed through ui
  if (updateBody?.hasOwnProperty?.('invoiceNumber') || updateBody?.hasOwnProperty?.('vendor')) {
    const invoiceNumber = updateBody?.hasOwnProperty?.('invoiceNumber') ? updateBody.invoiceNumber : obj.invoiceNumber;
    const vendor = updateBody?.hasOwnProperty?.('vendor') ? updateBody.vendor : obj?.vendor?._id;
    const dup = await getDuplicateInvoice(invoiceNumber, vendor, {
      _id: { $ne: parseInt(id) },
    });
    if (dup) {
      throw new ApiError(httpStatus.BAD_REQUEST, 'Duplicate Invoice Number');
    }

const { resubmit } = updateBody;

if (resubmit) {
  // if (obj.amApprovalRequired === true) {
  //   updateBody.assignedTo = 'AM';
  //   updateBody.amApproved = 'Open';
  // } else {
  //   updateBody.assignedTo = 'Finance';
  // }
  if (AM_APPROVAL_REQUIRED_INVOICE_TYPES.includes(updateBody.invoiceType)) {
    updateBody.assignedTo = 'AM';
    updateBody.amApprovalRequired = true;
    updateBody.amApproved = 'Open';
    updateBody.amApprovedAt = null;
    updateBody.rmApproved = null;
    // updateBody.rmApprovedAt = null;
    // updateBody.rmComments = '';
  } else {
    updateBody.assignedTo = 'Finance';
    updateBody.amApprovalRequired = false;
  }
  // if (obj.rmApprovalRequired) {
  //   updateBody.rmApproved = null;
  //   updateBody.rmApprovedAt = null;
  //   updateBody.rmComments = '';
  // }

  updateBody.financeUserApproved = 'Open';
  updateBody.financeUserApprovedAt = null;
  updateBody.financeUserComments = '';

  await logAuditEvent(constants.EVENT_TYPE.RESUBMIT_INVOICE, id, obj, updateBody);

if (incomingStatus == 'CREDIT_ISSUED') {
  updateBody.assignedTo = _case?.admin?._id;
  updateBody.assignToUserTable = tableKeys.user;
  // If user does not belongs to DC and user is not vegetable vendor, then user is not allowed to issue credit
  if (user?.role?.belongsTo != 'DC' && !isVegetableVendor && roleType !== roles.admin) {
    throw new ApiError(httpStatus.BAD_REQUEST, 'Invalid Request');
  }
  // If user is a vegetable vendor and vendor id from case is not equal to user.vendor or user's id, then request is not correct
  if (isVegetableVendor && caseVendorId != user.vendor && caseVendorId != parseInt(user._id)) {
    throw new ApiError(httpStatus.BAD_REQUEST, 'Invalid Request');
  }
  // Action taker is not allowed to Issue credit
  if (roleType == roles.actionTaker) {
    throw new ApiError(httpStatus.BAD_REQUEST, 'Invalid Request');
  }

  // If user is not vegetable vendor, then belongs to DC, we check dc for the case with user's id for action taker, credit issuer, distributor
  if (roleType !== roles.admin) {
    if (
      !isVeget

ableVendor &&
        caseDcId != parseInt(user.id) &&
        !user?.distributors?.includes(caseDcId) &&
        parseInt(caseDcId) != parseInt(user.dc)
      ) {
        throw new ApiError(httpStatus.BAD_REQUEST, 'Invalid Request');
      }
    }

if ('status' in updateBody && updateBody.status === 'CLOSED') {
  if (!_case.closedByAdminAt) {
    throw new ApiError(httpStatus.BAD_REQUEST, 'Closure By Admin is required.');
  }
  updateBody.assignedTo = null;
  updateBody.adoptedBy = null;
  if (user?.role?.type != 'ADMIN' && user?.role?.type != 'R&D') {
    throw new ApiError(httpStatus.BAD_REQUEST, 'Only admin can close case');
  }
  updatedBodyForTimeline.status = 'Closed';

  // VALID NEXT STATE CHECKS
  const nextValidStatuses = caseMap[curStatus];

  if ('status' in updateBody && nextValidStatuses && !nextValidStatuses.includes(incomingStatus)) {
    throw new ApiError(httpStatus.BAD_REQUEST, 'Invalid case status promotion');
  }
  if (updateBody.status === 'REVIEW_BY_ADMIN') {
    reason = 'Review by Admin';
  }
}

if (
  ['FAULT_ACCEPTED_BY_DC', 'FAULT_ACCEPTED_BY_VENDOR'].includes(updateBody.status) &&
  updateBody.fault &&
  !['DC', 'VENDOR'].includes(updateBody.fault.acceptedBy)
) {
  throw new ApiError(httpStatus.BAD_REQUEST, 'Accepted By can be DC / Vendor');
}

// ADOPTION CHECKS
const isAdoptedByDC = 'ADOPTED_BY_DC' === incomingStatus;
const isAdoptedByVendor = 'ADOPTED_BY_VENDOR' === incomingStatus;
const adoptedByUser = await User.findById(updateBody.adoptedBy);
if (isAdoptedByDC && adoptedByUser.role.belongsTo !== 'DC') {
