const createWaiverAssignment = async (waiverAssignmentBody) => {
  const { store, sequenceNo, satelliteNo } = waiverAssignmentBody;
  const storeData = await Store.findOne({ storeNo: store, sequenceNo, satelliteNo });

  if (!storeData) {
