  const waiverAssignment = await WaiverAssignment.create(waiverAssignmentBody);
  return waiverAssignment;
};

const getOpenTicketsWithSLAExpired = async () => {
  const departmentService = require('./departments.service');

  const curDate = convertTZ(new Date(), 'Asia/Kolkata');
  let filter = {};
  // Getting department where we do not have to send escalation notification for weekend
  if (curDate.getDay() === 0 || curDate.getDay() === 6) {
    const department = await departmentService.getDepartmentMap({ holdWeekEndEscalations: true }, false);
    const departmentIds = department.map((item) => item.id);
    filter.dept = { $nin: departmentIds };
  }

  const tickets = await Ticket.find({
    status: ticketStatusTypes.OPENED,
    ticketType: { $in: [ticketTypes.INTERNAL, ticketTypes.EXTERNAL] },
    $or: [{ holdEscalations: null }, { holdEscalations: false }],
    archive: false,
    slaExpiry: {
      $lte: new Date(),
    },
    ...filter,
  }).populate('category complaintForm');
  const stores = tickets?.reduce?.((unqiueMap, ticket) => {
    const { store } = ticket;
    if (store) {
      unqiueMap[store] = true;
    }

const nextLevel = currentLevel + 1;
if (category && category.escalationMatrix) {
  const filteredNextLevel = category.escalationMatrix.filter((x) => x.no === nextLevel);
  t.escalatedAtleastOnce = true;
  if ([...filteredNextLevel].length > 0) {
    logger.info(`Ticket #${t.id} is escalated from cur level ${currentLevel} to next level ${nextLevel}`);
    t.sla = nextLevel;
    const today = new Date();
    today.setHours(today.getHours() + +filteredNextLevel[0].sla);
    await ticketService.updateTicketById(+t.id, { sla: nextLevel, slaExpiry: today.toISOString() });
