const updateAppDocumentById = async (id, updatedBody, slug, app) => {
  const document = await AppDocument.findOne({ _id: id, slug });
  const appProperties = app?.properties?.document;

  if (!document) {
    throw new ApiError(httpStatus.NOT_FOUND, 'App document not found');
  }
  // We need to unconfirm the documents which are already confirmed when we are allowed to confirm documents for an app
  if (appProperties?.allowConfirm) {
    const appKey = `limits.${app._id}`;
    const roleCond = app?.roles?.reduce?.((list, item) => {
      list.push({ [appKey]: item }, { [appKey]: `${item}` });
      return list;
    }, []);
    const deptRoles = app?.properties?.document?.deptMappingRoles;
    const departments = document?.documentCategory?.departments?.map?.((item) => item._id);
    const userPipeline = appDocumentPipeline.documentUserEmails(roleCond, appKey, deptRoles, departments);
    const emails = (await User.aggregate(userPipeline))?.[0]?.emails;
    try {
      let emailMsgContent = appProperties?.emailMsgContent;
      if (appProperties?.emailMsgContent) {
        emailMsgContent = emailMsgContent
          .replace(new RegExp('{{name}}', 'g'), document?.fileName || '')
          .replace(new RegExp('{{portalLink}}', 'g'), `${urls.pulsePortal}${app.link}` || '');
      }
      const emailTemplate = documentUpdateTemplate(appProperties?.emailTemplateSubject, emailMsgContent, {
        documentName: document?.fileName,
        appLink: app.link,
      });
      sendEmailWithHTML(emails, appProperties?.emailSubject || 'Document Updated', emailTemplate);
    } catch (err) {
      logger.info('Error occurred while sending email for confirming document');
    }
    await ConfirmAppDocument.updateMany({ appDocumentId: id }, { isConfirmed: false });
  }

