const collectStepInputs = (stepMaster, inputs = {}, { skipRequiredCheck = false } = {}) => {
  const fields = stepMaster?.inputFields || [];
  const collected = {};
  const isBlank = (v) => v === undefined || v === null || v === '';
  const isRequiredMissing = (field, value) => field.required && !skipRequiredCheck && isBlank(value);

  // Field applies only when inputs[showWhen.key] is in showWhen.valueIn (else it's inactive).
  const isFieldActive = (field) => {
    if (!field.showWhen || !field.showWhen.key) return true;
    return (field.showWhen.valueIn || []).includes(inputs[field.showWhen.key]);
  };

  fields.forEach((field) => {
    if (!isFieldActive(field)) return;

    const value = inputs[field.key];

    if (field.type === 'DROPDOWN') {
      if (isRequiredMissing(field, value)) {
        throw new ApiError(httpStatus.BAD_REQUEST, `Missing required input: ${field.label || field.key}`);
      }
      if (!isBlank(value) && field.options?.length && !field.options.includes(value)) {
        throw new ApiError(httpStatus.BAD_REQUEST, `Invalid value for ${field.label || field.key}`);
      }
      if (!isBlank(value)) collected[field.key] = value;

      // Conditional upload tied to the selected dropdown value.
      if (field.fileUpload && !isBlank(value) && (field.fileUpload.whenValueIn || []).includes(value)) {
        const fileKey = field.fileUpload.key || `${field.key}File`;
        const fileVal = inputs[fileKey];
        if (!skipRequiredCheck && isBlank(fileVal)) {
          throw new ApiError(httpStatus.BAD_REQUEST, `Missing required upload: ${field.fileUpload.label || fileKey}`);
        }
        collected[fileKey] = fileVal;
      }
    } else if (field.type === 'UPLOAD') {
      if (isRequiredMissing(field, value)) {
        throw new ApiError(httpStatus.BAD_REQUEST, `Missing required upload: ${field.label || field.key}`);
      }
      if (!isBlank(value)) collected[field.key] = value;
    } else if (field.type === 'DATE' || field.type === 'TEXT') {
      if (isRequiredMissing(field, value)) {
        throw new ApiError(httpStatus.BAD_REQUEST, `Missing required input: ${field.label || field.key}`);
      }
      if (!isBlank(value)) collected[field.key] = value;
    } else if (field.type === 'NUMBER') {
      if (isRequiredMissing(field, value)) {
        throw new ApiError(httpStatus.BAD_REQUEST, `Missing required input: ${field.label || field.key}`);
      }
      if (!isBlank(value)) {
        const num = Number(value);
        if (Number.isNaN(num)) {
          throw new ApiError(httpStatus.BAD_REQUEST, `Invalid number for ${field.label || field.key}`);
